import{_ as e,o as l,c as a,a2 as i}from"./chunks/framework.RQXGjTIX.js";const d="/appliedcraftedenergistics/cell-style.png",m=JSON.parse('{"title":"气体存储元件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cells.md","filePath":"guide/cells.md"}'),r={name:"guide/cells.md"};function s(g,t,n,o,h,c){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="气体存储元件" tabindex="-1">气体存储元件 <a class="header-anchor" href="#气体存储元件" aria-label="Permalink to &quot;气体存储元件&quot;">​</a></h1><p>气体存储元件是 CCB 气体进入 ME 网络后的“仓库”。共十档：</p><table tabindex="0"><thead><tr><th>元件</th><th style="text-align:right;">AE 字节</th><th style="text-align:right;">气体容量（GU）</th><th style="text-align:right;">相当于 1 atm 下的体积</th></tr></thead><tbody><tr><td>1k</td><td style="text-align:right;">1,024</td><td style="text-align:right;">1,024,000</td><td style="text-align:right;">1,024 m³</td></tr><tr><td>4k</td><td style="text-align:right;">4,096</td><td style="text-align:right;">4,096,000</td><td style="text-align:right;">4,096 m³</td></tr><tr><td>16k</td><td style="text-align:right;">16,384</td><td style="text-align:right;">16,384,000</td><td style="text-align:right;">16,384 m³</td></tr><tr><td>64k</td><td style="text-align:right;">65,536</td><td style="text-align:right;">65,536,000</td><td style="text-align:right;">65,536 m³</td></tr><tr><td>256k</td><td style="text-align:right;">262,144</td><td style="text-align:right;">262,144,000</td><td style="text-align:right;">262,144 m³</td></tr><tr><td>1M</td><td style="text-align:right;">1,048,576</td><td style="text-align:right;">1,048,576,000</td><td style="text-align:right;">1,048,576 m³</td></tr><tr><td>4M</td><td style="text-align:right;">4,194,304</td><td style="text-align:right;">4,194,304,000</td><td style="text-align:right;">4,194,304 m³</td></tr><tr><td>16M</td><td style="text-align:right;">16,777,216</td><td style="text-align:right;">16,777,216,000</td><td style="text-align:right;">16,777,216 m³</td></tr><tr><td>64M</td><td style="text-align:right;">67,108,864</td><td style="text-align:right;">67,108,864,000</td><td style="text-align:right;">67,108,864 m³</td></tr><tr><td>256M</td><td style="text-align:right;">268,435,456</td><td style="text-align:right;">268,435,456,000</td><td style="text-align:right;">268,435,456 m³</td></tr></tbody></table><p><img src="'+d+'" alt="气体元件与 AE2 元件样式对比"></p><p>换算契约：<strong>1 AE byte = 1,000 GU</strong>，而 <code>1 GU = 100 kPa 下的 1 升气体</code>。 所以元件容量（GU）除以 1,000 就是它占用的 AE 字节数，也等于“多少立方米的常压气体”。</p><h2 id="元件是什么、不是什么" tabindex="-1">元件是什么、不是什么 <a class="header-anchor" href="#元件是什么、不是什么" aria-label="Permalink to &quot;元件是什么、不是什么&quot;">​</a></h2><ul><li>元件<strong>只保存气体的数量</strong>，不保存气压；把同一只元件从 ME 驱动器里拿出来、放进去，气压不会“变化”， 因为它本来就没有气压这个概念。</li><li>元件不承担 CCB 的过压 / 破裂机制；气体进出网络的压力由 <a href="/appliedcraftedenergistics/guide/interface.html">ME 气体接口</a> 和 <a href="/appliedcraftedenergistics/guide/p2p.html">气体 P2P 隧道</a> 背后的真实容器负责。</li><li>每种气体都会占用一部分字节（与 AE2 流体元件一致），所以“存得下多少种”和“存得下多少量”是两回事。</li></ul><h2 id="高容量档与-mega-cells" tabindex="-1">高容量档与 MEGA Cells <a class="header-anchor" href="#高容量档与-mega-cells" aria-label="Permalink to &quot;高容量档与 MEGA Cells&quot;">​</a></h2><p>1M–256M 元件本身在所有安装中都会注册，但它们的<strong>默认配方以 MEGA Cells 为前置</strong>：</p><ul><li>使用 <code>megacells:mega_item_cell_housing</code>；</li><li>使用 <code>megacells:cell_component_&lt;档位&gt;</code>；</li><li>另加 CCB 气密板 / 气体罐和 1–2 个气密储罐。</li></ul><p>配方文件带 <code>neoforge:mod_loaded</code> 条件，因此<strong>只有安装 MEGA Cells 时，默认的 1M–256M 配方才会加载和显示</strong>。 配置项 <code>recipes.enable_mega_cell_recipes</code> 可以移除这些默认配方；数据包也可以提供自定义配方。 详见 <a href="/appliedcraftedenergistics/guide/config.html">配置文件</a>。</p><h2 id="放入网络" tabindex="-1">放入网络 <a class="header-anchor" href="#放入网络" aria-label="Permalink to &quot;放入网络&quot;">​</a></h2><p>把元件放进 <strong>ME 驱动器</strong>或 <strong>ME 箱子</strong>即可被网络读写。空元件可以用 AE2 的方式拆解回收。</p><h2 id="终端显示" tabindex="-1">终端显示 <a class="header-anchor" href="#终端显示" aria-label="Permalink to &quot;终端显示&quot;">​</a></h2><p>气体在终端里按气体名排序，图标是按气体颜色绘制的“雾气”图标，数量以 <strong>kGU</strong> 显示 （1 kGU = 1,000 GU）。与物品 / 流体混在同一个终端里，一次搜索即可。</p><h2 id="升级槽" tabindex="-1">升级槽 <a class="header-anchor" href="#升级槽" aria-label="Permalink to &quot;升级槽&quot;">​</a></h2><p>元件有 <strong>5 个升级槽</strong>，在<strong>元件工作台</strong>里安装：</p><ul><li>AE2 原生卡：反相卡、均分卡、溢出销毁卡；</li><li>气体专属卡：高压卡、扩容卡、多类型卡、泄压阀卡。</li></ul><p>装卡后元件的<strong>字节上限</strong>会变化，因此终端里显示的容量会变大，这不代表元件“降级”—— 详见 <a href="/appliedcraftedenergistics/guide/upgrades.html">元件升级卡</a>。</p><h2 id="游戏内教程" tabindex="-1">游戏内教程 <a class="header-anchor" href="#游戏内教程" aria-label="Permalink to &quot;游戏内教程&quot;">​</a></h2><p>全部十档元件都登记在 GuideME 的 <code>item_ids</code> 中。把鼠标放在任意气体元件上，按 <strong>G</strong> 即可打开本页。</p><div class="tip custom-block"><p class="custom-block-title">分区</p><p>和物品元件一样，气体元件也支持在元件工作台里填写分区。分区决定它接受哪些气体； 反相卡会反转分区列表的含义（白名单 ⇄ 黑名单）。</p></div>',22)])])}const x=e(r,[["render",s]]);export{m as __pageData,x as default};
